import base64


def create_hazard_in_pg(hazard: Hazard_Model):
    try:
        with Session(engine) as session:
            inserted_hazard = Hazard(type_name=hazard.type_name
                                     , id=base64.b64encode(hazard.type_name.encode("ascii")).decode("ascii") + "-" + hazard.id
                                     , geo_polygon=func.ST_GeomFromText(hazard.geo_polygon, 4326),
                                     start_time=hazard.start_time
                                     , end_time=hazard.end_time, people_ids=hazard.people_ids,
                                     buildings_ids=hazard.buildings_ids)
            session.add(inserted_hazard)
            session.commit()
        return "Hazard created successfully"
    except Exception as e:
        return f"Error creating Hazard: {str(e)}"


def delete_hazard_in_pg_by_type_name(id: str, type_name: str):
    id_with_prefix = base64.b64encode(type_name.encode("ascii")).decode("ascii") + "-" + id
    return delete_record(id_with_prefix, Hazard, Hazard.id)


